// Safe WhatsApp payload extractor supporting Meta Cloud API, Twilio & generic payloads
const body = $input.item.json.body || $input.item.json;
let phone = '';
let customerName = 'Customer';
let message = '';
let channel = 'whatsapp';

if (body.entry && body.entry[0]?.changes && body.entry[0].changes[0]?.value) {
  // Meta WhatsApp Cloud API format
  const val = body.entry[0].changes[0].value;
  if (val.contacts && val.contacts[0]) {
    customerName = val.contacts[0].profile?.name || customerName;
  }
  if (val.messages && val.messages[0]) {
    const msgObj = val.messages[0];
    phone = msgObj.from || '';
    if (msgObj.type === 'text') {
      message = msgObj.text?.body || '';
    } else if (msgObj.type === 'interactive') {
      message = msgObj.interactive?.button_reply?.title || msgObj.interactive?.list_reply?.title || '';
    } else if (msgObj.type === 'button') {
      message = msgObj.button?.text || '';
    }
  }
} else if (body.From || body.Body) {
  // Twilio format
  phone = (body.From || '').replace('whatsapp:', '').trim();
  customerName = body.ProfileName || customerName;
  message = body.Body || '';
  channel = 'twilio';
} else {
  // Direct generic json format
  phone = String(body.phone || body.from || body.sender || '').replace(/[^0-9+]/g, '').trim();
  customerName = body.name || body.customer_name || body.customerName || customerName;
  message = body.message || body.text || body.body || '';
}

phone = phone.replace(/[^0-9]/g, '');

return [{
  json: {
    phone: phone,
    customer_name: customerName,
    message: (message || '').trim(),
    channel: channel,
    received_at: new Date().toISOString()
  }
}];

// Retrieve input from inbound parser and DB query
const inbound = $('Parse_WhatsApp_Inbound').first().json;
const dbItems = $input.all().map(i => i.json).filter(j => j.appointment_id);

const activePending = dbItems.find(a => a.status === 'PENDING');
const activeConfirmed = dbItems.find(a => a.status === 'CONFIRMED' || a.status === 'RESCHEDULED');

// Clinic configuration
const clinicConfig = {
  name: "Apex Healthcare Clinic",
  timezone: "UTC",
  working_hours: {
    start: "09:00",
    end: "17:00",
    slot_duration_minutes: 30,
    buffer_minutes: 0,
    working_days: ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"],
    closed_days: ["Sunday"]
  },
  doctors: [
    { id: "dr_smith", name: "Dr. John Smith", specialty: "General Physician" },
    { id: "dr_emily", name: "Dr. Emily Davis", specialty: "Dental Specialist" },
    { id: "dr_robert", name: "Dr. Robert Wilson", specialty: "Cardiologist" }
  ],
  services: [
    "General Consultation",
    "Dental Checkup",
    "Teeth Cleaning",
    "Cardiology Consultation",
    "ECG & Follow-up"
  ]
};

const now = new Date();
const todayStr = now.toISOString().split('T')[0];
const dayOfWeek = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"][now.getDay()];

// Build system prompt for Gemini
const prompt = `You are an intelligent clinical appointment receptionist AI for ${clinicConfig.name}.
Current Date: ${todayStr} (${dayOfWeek}).
Clinic Working Hours: 09:00 - 17:00, Monday to Saturday. Closed on Sundays.
Doctors Available:
${clinicConfig.doctors.map(d => `- ${d.id}: ${d.name} (${d.specialty})`).join('\n')}
Services: ${clinicConfig.services.join(', ')}

Customer Information:
- Name: ${inbound.customer_name || 'Valued Patient'}
- Phone: ${inbound.phone}
- Latest Customer Message: "${inbound.message}"

Customer Active Context:
- Pending Hold Appointment: ${activePending ? JSON.stringify(activePending) : 'None'}
- Confirmed Upcoming Appointment: ${activeConfirmed ? JSON.stringify(activeConfirmed) : 'None'}

Your Task:
Analyze the message and return a strictly structured JSON response.

Intents:
1. "BOOK" -> Customer wants to book a new appointment or picked a specific date/time/doctor.
2. "CHECK_AVAILABILITY" -> Customer is asking if a doctor or time slot is free without explicitly confirming booking yet.
3. "CONFIRM" -> Customer says "YES", "CONFIRM", "OK", "Sure", "book it", or confirms the pending slot.
4. "RESCHEDULE" -> Customer wants to change the date/time of their existing appointment.
5. "CANCEL" -> Customer wants to cancel their appointment.
6. "GENERAL_QUESTIONS" -> Customer is asking general queries (services, doctor info, address, working hours).
7. "UNKNOWN" -> Any unintelligible or unrelated query.

IMPORTANT INSTRUCTIONS:
- If there is an active Pending Hold appointment and customer says "YES", "CONFIRM", "Y", "Sure", "go ahead" -> INTENT IS "CONFIRM".
- DO NOT invent calendar availability. Google Calendar is the source of truth.
- Extract requested_date in YYYY-MM-DD format (resolve relative dates like "tomorrow", "next Monday", "Wednesday").
- Extract requested_time in 24-hour HH:MM format (e.g. 09:30, 14:00, 16:30).
- Extract doctor_id matching one of [dr_smith, dr_emily, dr_robert] or default to dr_smith if unspecified.
- Extract service if mentioned.

Output MUST be a single raw JSON object with this exact structure:
{
  "intent": "BOOK" | "CHECK_AVAILABILITY" | "CONFIRM" | "RESCHEDULE" | "CANCEL" | "GENERAL_QUESTIONS" | "UNKNOWN",
  "doctor_id": "dr_smith" | "dr_emily" | "dr_robert" | null,
  "doctor_name": string | null,
  "service": string | null,
  "requested_date": "YYYY-MM-DD" | null,
  "requested_time": "HH:MM" | null,
  "appointment_id": number | null,
  "general_answer": string | null,
  "notes": string | null
}`;

return [{
  json: {
    phone: inbound.phone,
    customer_name: inbound.customer_name,
    message: inbound.message,
    channel: inbound.channel,
    received_at: inbound.received_at,
    active_pending: activePending || null,
    active_confirmed: activeConfirmed || null,
    all_db_appointments: dbItems,
    clinic_config: clinicConfig,
    today_str: todayStr,
    gemini_prompt: prompt
  }
}];

const prev = $('Merge_Context_For_AI').first().json;
const response = $input.item.json;

let aiResult = {
  intent: 'UNKNOWN',
  doctor_id: 'dr_smith',
  doctor_name: 'Dr. John Smith',
  service: 'General Consultation',
  requested_date: null,
  requested_time: null,
  appointment_id: null,
  general_answer: null,
  notes: null
};

// Check user quick confirmation keywords directly
const cleanMsg = (prev.message || '').trim().toLowerCase();
const isDirectConfirm = ['yes', 'confirm', 'y', 'sure', 'ok', 'okay', 'proceed', 'book it', 'yes please', 'confirm please'].includes(cleanMsg);

if (prev.active_pending && isDirectConfirm) {
  aiResult.intent = 'CONFIRM';
  aiResult.appointment_id = prev.active_pending.appointment_id;
  aiResult.doctor_id = prev.active_pending.doctor_id;
  aiResult.service = prev.active_pending.service;
} else if (response && response.candidates && response.candidates[0]?.content?.parts?.[0]?.text) {
  try {
    let rawText = response.candidates[0].content.parts[0].text.trim();
    if (rawText.startsWith('```json')) {
      rawText = rawText.replace(/^```json\n?/, '').replace(/\n?```$/, '');
    } else if (rawText.startsWith('```')) {
      rawText = rawText.replace(/^```\n?/, '').replace(/\n?```$/, '');
    }
    const parsed = JSON.parse(rawText);
    aiResult = { ...aiResult, ...parsed };
  } catch (e) {
    if (cleanMsg.includes('cancel')) aiResult.intent = 'CANCEL';
    else if (cleanMsg.includes('reschedule') || cleanMsg.includes('change')) aiResult.intent = 'RESCHEDULE';
    else if (cleanMsg.includes('book') || cleanMsg.includes('appointment')) aiResult.intent = 'BOOK';
    else if (cleanMsg.includes('available') || cleanMsg.includes('free')) aiResult.intent = 'CHECK_AVAILABILITY';
    else aiResult.intent = 'GENERAL_QUESTIONS';
  }
} else {
  if (prev.active_pending && isDirectConfirm) {
    aiResult.intent = 'CONFIRM';
  } else if (cleanMsg.includes('cancel')) {
    aiResult.intent = 'CANCEL';
  } else if (cleanMsg.includes('reschedule')) {
    aiResult.intent = 'RESCHEDULE';
  } else if (cleanMsg.includes('book') || cleanMsg.includes('slot')) {
    aiResult.intent = 'BOOK';
  } else {
    aiResult.intent = 'GENERAL_QUESTIONS';
    aiResult.general_answer = 'Welcome to Apex Healthcare Clinic! You can book an appointment, check available doctor slots, reschedule, or cancel anytime. How may we assist you today?';
  }
}

const doctorMap = {
  dr_smith: 'Dr. John Smith (General Physician)',
  dr_emily: 'Dr. Emily Davis (Dental Specialist)',
  dr_robert: 'Dr. Robert Wilson (Cardiologist)'
};

if (!aiResult.doctor_id && prev.active_pending) {
  aiResult.doctor_id = prev.active_pending.doctor_id;
}
if (!aiResult.doctor_id && prev.active_confirmed) {
  aiResult.doctor_id = prev.active_confirmed.doctor_id;
}
if (!aiResult.doctor_id) {
  aiResult.doctor_id = 'dr_smith';
}
aiResult.doctor_name = doctorMap[aiResult.doctor_id] || 'Dr. John Smith (General Physician)';

return [{
  json: {
    phone: prev.phone,
    customer_name: prev.customer_name,
    message: prev.message,
    channel: prev.channel,
    received_at: prev.received_at,
    active_pending: prev.active_pending,
    active_confirmed: prev.active_confirmed,
    all_db_appointments: prev.all_db_appointments,
    clinic_config: prev.clinic_config,
    today_str: prev.today_str,
    intent: (aiResult.intent || 'GENERAL_QUESTIONS').toUpperCase(),
    doctor_id: aiResult.doctor_id,
    doctor_name: aiResult.doctor_name,
    service: aiResult.service || 'General Consultation',
    requested_date: aiResult.requested_date,
    requested_time: aiResult.requested_time,
    appointment_id: aiResult.appointment_id || (prev.active_pending ? prev.active_pending.appointment_id : null),
    general_answer: aiResult.general_answer,
    notes: aiResult.notes
  }
}];

const item = $input.item.json;
let needsInfo = false;
let missingFields = [];
let replyMsg = '';

if (!item.requested_date) {
  needsInfo = true;
  missingFields.push('preferred date (e.g., Tomorrow, 2026-09-10)');
}

if (!item.requested_time) {
  needsInfo = true;
  missingFields.push('preferred time (e.g., 10:00 AM, 02:30 PM)');
}

if (needsInfo) {
  replyMsg = `Hello ${item.customer_name || 'there'}! To check availability with ${item.doctor_name || 'our doctor'}, please provide your ${missingFields.join(' and ')}.`;
} else {
  const dateObj = new Date(`${item.requested_date}T${item.requested_time}:00Z`);
  const day = dateObj.getUTCDay();
  if (day === 0) {
    needsInfo = true;
    replyMsg = `We are closed on Sundays. Our working hours are Monday to Saturday, 09:00 to 17:00. Please select another date.`;
  } else {
    const [hh, mm] = item.requested_time.split(':').map(Number);
    if (hh < 9 || (hh === 17 && mm > 0) || hh > 17) {
      needsInfo = true;
      replyMsg = `Our clinic working hours are 09:00 to 17:00. The requested time (${item.requested_time}) is outside working hours. Please pick a slot between 09:00 and 16:30.`;
    }
  }
}

const startIso = item.requested_date ? `${item.requested_date}T00:00:00.000Z` : new Date().toISOString();
const endIso = item.requested_date ? `${item.requested_date}T23:59:59.000Z` : new Date(Date.now() + 86400000).toISOString();

return [{
  json: {
    ...item,
    needs_info: needsInfo,
    missing_fields: missingFields,
    missing_info_message: replyMsg,
    gcal_time_min: startIso,
    gcal_time_max: endIso
  }
}];

const prev = $('Validate_Booking_Input').first().json;
const gcalItems = $input.all().map(i => i.json).filter(j => j.id || j.start);

const reqDate = prev.requested_date;
const reqTime = prev.requested_time;
const slotDuration = prev.clinic_config?.working_hours?.slot_duration_minutes || 30;

const reqStart = new Date(`${reqDate}T${reqTime}:00Z`);
const reqEnd = new Date(reqStart.getTime() + slotDuration * 60000);

function isOverlap(startA, endA, events) {
  for (const ev of events) {
    const evStartStr = ev.start?.dateTime || ev.start?.date;
    const evEndStr = ev.end?.dateTime || ev.end?.date;
    if (!evStartStr || !evEndStr) continue;
    const evStart = new Date(evStartStr);
    const evEnd = new Date(evEndStr);
    if (startA < evEnd && endA > evStart) {
      return true;
    }
  }
  return false;
}

const isRequestedFree = !isOverlap(reqStart, reqEnd, gcalItems);

const allDaySlots = [];
const startHour = 9;
const endHour = 17;

for (let h = startHour; h < endHour; h++) {
  for (let m = 0; m < 60; m += slotDuration) {
    const hhStr = String(h).padStart(2, '0');
    const mmStr = String(m).padStart(2, '0');
    const timeStr = `${hhStr}:${mmStr}`;
    const sTime = new Date(`${reqDate}T${timeStr}:00Z`);
    const eTime = new Date(sTime.getTime() + slotDuration * 60000);

    const now = new Date();
    if (sTime <= now) continue;

    if (!isOverlap(sTime, eTime, gcalItems)) {
      allDaySlots.push(timeStr);
    }
  }
}

const alternatives = allDaySlots.slice(0, 4);

return [{
  json: {
    ...prev,
    is_slot_available: isRequestedFree,
    start_time_iso: reqStart.toISOString(),
    end_time_iso: reqEnd.toISOString(),
    available_alternatives: alternatives,
    existing_events_count: gcalItems.length
  }
}];

const item = $input.item.json;
const alts = item.available_alternatives || [];
let msg = '';

if (alts.length > 0) {
  msg = `⚠️ Sorry, ${item.doctor_name || 'the doctor'} is not available on ${item.requested_date} at ${item.requested_time}.\n\nHere are the next available slots on ${item.requested_date}:\n` +
        alts.map(s => `🔹 ${s}`).join('\n') +
        `\n\nPlease reply with your preferred time from the list above to proceed with booking.`;
} else {
  msg = `⚠️ Sorry, all appointment slots for ${item.doctor_name || 'the doctor'} are fully booked on ${item.requested_date}.\n\nPlease suggest another date (e.g., the following working day) and we will check availability immediately!`;
}

return [{
  json: {
    ...item,
    unavailable_whatsapp_msg: msg
  }
}];

