const prev = $('Calculate_Available_Slots').first().json;
const appt = $input.item.json;

const dateStr = prev.requested_date;
const timeStr = prev.requested_time;
const doctor = prev.doctor_name || prev.doctor_id;
const service = prev.service || 'Consultation';

const message = `📋 *APPOINTMENT PROPOSAL (PENDING CONFIRMATION)*\n\n` +
`👤 Patient: ${prev.customer_name || 'Valued Patient'}\n` +
`👨‍⚕️ Doctor: ${doctor}\n` +
`💼 Service: ${service}\n` +
`📅 Date: ${dateStr}\n` +
`⏰ Time: ${timeStr}\n\n` +
`We have tentatively held this slot for you.\n` +
`👉 *Please reply YES or CONFIRM to finalize your booking.*`;

return [{
  json: {
    ...prev,
    appointment_id: appt.appointment_id,
    pending_whatsapp_msg: message
  }
}];

const prev = $input.item.json;
const pending = prev.active_pending;

if (!pending || !pending.start_time || !pending.end_time) {
  return [{
    json: {
      ...prev,
      has_valid_pending: false,
      error_msg: "You do not currently have any pending appointment held. Reply with a date and time (e.g. 'Book tomorrow at 10 AM') to start a new booking."
    }
  }];
}

return [{
  json: {
    ...prev,
    has_valid_pending: true,
    appointment_id: pending.appointment_id,
    start_time_iso: new Date(pending.start_time).toISOString(),
    end_time_iso: new Date(pending.end_time).toISOString(),
    doctor_id: pending.doctor_id,
    service: pending.service,
    customer_name: pending.customer_name || prev.customer_name
  }
}];

const prev = $('Validate_Pending_For_Confirm').first().json;
const gcalItems = $input.all().map(i => i.json).filter(j => j.id || j.start);

const reqStart = new Date(prev.start_time_iso);
const reqEnd = new Date(prev.end_time_iso);

let isFree = true;
for (const ev of gcalItems) {
  const evStart = new Date(ev.start?.dateTime || ev.start?.date);
  const evEnd = new Date(ev.end?.dateTime || ev.end?.date);
  if (reqStart < evEnd && reqEnd > evStart) {
    isFree = false;
    break;
  }
}

return [{
  json: {
    ...prev,
    is_final_slot_free: isFree
  }
}];

