const prev = $('Verify_Final_Availability').first().json;
const appt = $input.item.json;

const startDt = new Date(prev.start_time_iso);
const dateStr = startDt.toISOString().split('T')[0];
const timeStr = startDt.toISOString().split('T')[1].substring(0, 5);

const message = `🎉 *APPOINTMENT CONFIRMED!*\n\n` +
`✅ *Booking Reference:* #${appt.appointment_id || prev.appointment_id}\n` +
`👤 *Patient:* ${prev.customer_name}\n` +
`👨‍⚕️ *Doctor:* ${prev.doctor_name || prev.doctor_id}\n` +
`💼 *Service:* ${prev.service}\n` +
`📅 *Date:* ${dateStr}\n` +
`⏰ *Time:* ${timeStr} (UTC)\n\n` +
`📍 *Location:* Apex Healthcare Clinic, Main Facility\n\n` +
`We have added your appointment to our system. You will receive automatic reminders prior to your visit. Reply RESCHEDULE or CANCEL at any time if your plans change.`;

return [{
  json: {
    ...prev,
    appointment_id: appt.appointment_id || prev.appointment_id,
    confirmed_whatsapp_msg: message
  }
}];

const prev = $input.item.json;
const active = prev.active_confirmed;

if (!active) {
  return [{
    json: {
      ...prev,
      can_reschedule: false,
      error_msg: "You do not have any active confirmed appointment to reschedule. Reply with a date and time to book a new appointment."
    }
  }];
}

if (!prev.requested_date || !prev.requested_time) {
  const currentStart = new Date(active.start_time).toISOString().replace('T', ' ').substring(0, 16);
  return [{
    json: {
      ...prev,
      can_reschedule: false,
      error_msg: `Your current appointment (#${active.appointment_id}) is scheduled for ${currentStart}.\n\nPlease reply with your new requested date and time (e.g. 'Reschedule to tomorrow at 3 PM').`
    }
  }];
}

const slotDuration = prev.clinic_config?.working_hours?.slot_duration_minutes || 30;
const newStart = new Date(`${prev.requested_date}T${prev.requested_time}:00Z`);
const newEnd = new Date(newStart.getTime() + slotDuration * 60000);

return [{
  json: {
    ...prev,
    can_reschedule: true,
    appointment_id: active.appointment_id,
    calendar_event_id: active.calendar_event_id,
    new_start_iso: newStart.toISOString(),
    new_end_iso: newEnd.toISOString()
  }
}];

const prev = $('Validate_Reschedule_Request').first().json;
const gcalItems = $input.all().map(i => i.json).filter(j => j.id || j.start);

const reqStart = new Date(prev.new_start_iso);
const reqEnd = new Date(prev.new_end_iso);

let isFree = true;
for (const ev of gcalItems) {
  if (prev.calendar_event_id && ev.id === prev.calendar_event_id) continue;
  const evStart = new Date(ev.start?.dateTime || ev.start?.date);
  const evEnd = new Date(ev.end?.dateTime || ev.end?.date);
  if (reqStart < evEnd && reqEnd > evStart) {
    isFree = false;
    break;
  }
}

return [{
  json: {
    ...prev,
    is_reschedule_slot_free: isFree
  }
}];

