const prev = $input.item.json;
const reply = prev.general_answer || `Welcome to Apex Healthcare Clinic!\n\n📍 Location: 100 Health Avenue, Suite 400\n⏰ Hours: Monday - Saturday, 09:00 - 17:00 (Sundays Closed)\n📞 Reception: +1-800-555-APEX\n\nHow can we assist you today? You can reply with a date and time to book an appointment with our specialists.`;

return [{
  json: {
    ...prev,
    general_reply_text: reply
  }
}];

const items = $input.all().map(i => i.json).filter(j => j.appointment_id && j.reminder_tier && j.status === 'CONFIRMED');

const results = [];
for (const appt of items) {
  const startDt = new Date(appt.start_time);
  const dateStr = startDt.toISOString().split('T')[0];
  const timeStr = startDt.toISOString().split('T')[1].substring(0, 5);

  let timeNotice = '';
  if (appt.reminder_tier === '3D') timeNotice = 'in 3 days';
  else if (appt.reminder_tier === '1D') timeNotice = 'tomorrow';
  else if (appt.reminder_tier === '4H') timeNotice = 'in 4 hours';
  else if (appt.reminder_tier === '1H') timeNotice = 'in 1 hour';

  const body = `🔔 *APPOINTMENT REMINDER*\n\n` +
  `Hello ${appt.customer_name}, this is a friendly reminder for your upcoming appointment ${timeNotice}.\n\n` +
  `📋 *Reference:* #${appt.appointment_id}\n` +
