    function applyFilters() {
      const search = document.getElementById('search-box').value.toLowerCase();
      const doctor = document.getElementById('doctor-filter').value;
      const todayStr = new Date().toISOString().split('T')[0];

      let filtered = allAppointments.filter(a => {
        const startStr = (a.start_time || '').split('T')[0];
        if (currentFilter === 'today' && startStr !== todayStr) return false;
        if (currentFilter === 'upcoming' && startStr < todayStr) return false;
        if (doctor && a.doctor_id !== doctor) return false;
        if (search) {
          const matchName = (a.customer_name || '').toLowerCase().includes(search);
          const matchPhone = (a.phone || '').includes(search);
          if (!matchName && !matchPhone) return false;
        }
        return true;
      });

      const todayList = allAppointments.filter(a => (a.start_time || '').split('T')[0] === todayStr);
      document.getElementById('stat-today').innerText = todayList.length;
      document.getElementById('stat-confirmed').innerText = todayList.filter(a => a.status === 'CONFIRMED').length;
      document.getElementById('stat-arrived').innerText = todayList.filter(a => a.status === 'ARRIVED').length;
      document.getElementById('stat-completed').innerText = todayList.filter(a => a.status === 'COMPLETED').length;

      renderTable(filtered);
    }

    function renderTable(list) {
      const tbody = document.getElementById('appointment-tbody');
      if (list.length === 0) {
        tbody.innerHTML = '<tr><td colspan="8" class="text-center py-4 text-muted">No appointments found for this filter.</td></tr>';
        return;
